import { ResponseError } from "../../errors.js";
import { Writer } from "../../protocol/writer.js";
import { createAPI } from "../definitions.js";
/*
  OffsetForLeaderEpoch Request (Version: 2) => [topics]
    topics => topic [partitions]
      topic => STRING
      partitions => partition current_leader_epoch leader_epoch
        partition => INT32
        current_leader_epoch => INT32
        leader_epoch => INT32
*/
export function createRequest(_replicaId, topics) {
    return Writer.create().appendArray(topics, (w, topic) => {
        w.appendString(topic.name, false).appendArray(topic.partitions, (w, partition) => {
            w.appendInt32(partition.partitionIndex)
                .appendInt32(partition.currentLeaderEpoch)
                .appendInt32(partition.leaderEpoch);
        }, false, false);
    }, false, false);
}
/*
  OffsetForLeaderEpoch Response (Version: 2) => throttle_time_ms [topics]
    throttle_time_ms => INT32
    topics => topic [partitions]
      topic => STRING
      partitions => error_code partition leader_epoch end_offset
        error_code => INT16
        partition => INT32
        leader_epoch => INT32
        end_offset => INT64
*/
export function parseResponse(_correlationId, apiKey, apiVersion, reader) {
    const errors = [];
    const response = {
        throttleTimeMs: reader.readInt32(),
        topics: reader.readArray((r, i) => ({
            topic: r.readString(false),
            partitions: r.readArray((r, j) => {
                const errorCode = r.readInt16();
                if (errorCode !== 0) {
                    errors.push([`/topics/${i}/partitions/${j}`, [errorCode, null]]);
                }
                return {
                    errorCode,
                    partition: r.readInt32(),
                    leaderEpoch: r.readInt32(),
                    endOffset: r.readInt64()
                };
            }, false, false)
        }), false, false)
    };
    if (errors.length) {
        throw new ResponseError(apiKey, apiVersion, Object.fromEntries(errors), response);
    }
    return response;
}
export const api = createAPI(23, 2, createRequest, parseResponse, false, false);
